// qa-checkpage-lock — LOCKS the check status page (the live call screen and the pull screen that
// follows it) in public/checkit.html. If an edit breaks any invariant below, the ship FAILS before it
// reaches the site.
//
// ── OWNER ORDER, 2026-07-31 ──
// This page is locked. No agent changes the pinned card, the footer rule, or the pull screen without
// the owner's express written consent naming this file. "It looked fine locally" is not consent. If you
// believe an invariant here is wrong, take it to the owner — do NOT edit this file to make your change
// pass. Every line below is a bug that already cost a day.
//
// ── WHAT THIS PAGE IS SUPPOSED TO DO ──
//   1. The call runs. The store card and Stop & hang up stay pinned at the top; the conversation
//      scrolls underneath them. There is no footer.
//   2. The call ends and the verdict is being pulled. The card STAYS, now reading "Getting results".
//      The result frame below skips its own placeholder headline so the message is not printed twice.
//   3. The verdict lands. The card disappears, the result page prints, the footer comes back.
//
// ── THE THREE TRAPS, IN THE ORDER THEY BIT ──
//
// TRAP 1 — a fixed filled box parked on the bottom edge flips iOS Safari's bottom bar to a flat grey
// that only a page reload clears. That is why the card is position:sticky and never position:fixed,
// and why the closed call sheet ships display:none (see qa-tint-lock). Do not "improve" the pin into a
// fixed header.
//
// TRAP 2 — a sticky element can only travel inside its OWN PARENT. The card was first parked inside
// #live. It held beautifully during the call, because #live was full of conversation. The moment the
// call ended #live emptied out and collapsed to the card's own height, so the card had nowhere left to
// travel and slid off the top while the result frame below kept scrolling. The card therefore lives in
// <main>, a sibling of #live and #result, whose height spans the page in BOTH states. Moving it back
// inside #live measures -443px on a scrolled pull screen. Do not move it.
//
// TRAP 3 — overflow-x:hidden on <body> silently makes body its own scrollport, and a sticky child
// measured against a box that never scrolls just rides away. overflow-x:clip trims the same overflow
// without creating a scroll container. The lview/pendbox override is load-bearing, not tidying.
//
// And the standing rule this page already carried: NEVER pad the live view out to a forced height to
// chase the chrome tint (tried 07-30, reverted the same day, guarded in qa-tint-lock). The follow-along
// aims at the newest line; dead space below the log strands it off-screen and kills the reveal.
//
// The behavioural half of this lock is scripts/test-live-view.mjs, which drives a real browser through
// a simulated call. This file also guards THAT file, so the browser proof cannot be quietly deleted.
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
const here = dirname(fileURLToPath(import.meta.url));
const html = readFileSync(join(here, "../public/checkit.html"), "utf8");
const live = readFileSync(join(here, "../scripts/test-live-view.mjs"), "utf8");
const all = readFileSync(join(here, "../scripts/test-all.sh"), "utf8");
let pass = 0, fail = 0;
const ok = (m) => { pass++; console.log(`  ✓ ${m}`); };
const no = (m) => { fail++; console.log(`  ✗ ${m}`); };
const has = (re, m) => (re.test(html) ? ok(m) : no(m));
const absent = (re, m) => (re.test(html) ? no(m) : ok(m));

console.log("\n▭▭▭ check status page LOCK ▭▭▭");

// ── A. The pinned card: one block, in the right parent, sticky and never fixed ──

// 1. The wrapper exists at all. Without it the card and the hang-up button drift apart on scroll.
has(/<div id="live_pin">/,
  "#live_pin exists — the store card and Stop & hang up are pinned as ONE block");

// 2. THE BIG ONE (trap 2). #live_pin must sit OUTSIDE #live. Checked structurally: take the slice of
//    markup from <div id="live" ...> to its matching sibling <!-- RESULT -->, and #live_pin must not be
//    in it. A regex alone would miss the nesting, which is exactly how this shipped broken once.
{
  const liveStart = html.indexOf('<div id="live" class="hidden">');
  const resultAt = html.indexOf('<div id="result"');
  const inside = liveStart >= 0 && resultAt > liveStart && html.slice(liveStart, resultAt).includes('id="live_pin"');
  const pinAt = html.indexOf('<div id="live_pin">');
  if (liveStart < 0 || resultAt < 0) no("could not find #live/#result to check where the card is parked — markup moved, re-check by hand");
  else if (inside) no("#live_pin is parked INSIDE #live — it will slide off the top the moment the call ends and #live collapses (trap 2). Put it back in <main>.");
  else if (pinAt < 0 || pinAt > liveStart) no("#live_pin must come BEFORE #live in <main>, so the card renders above the conversation");
  else ok("#live_pin lives in <main>, above #live — its parent spans the page in BOTH states (trap 2)");
}

// 3. Both pieces ride inside the wrapper.
{
  const pinAt = html.indexOf('<div id="live_pin">');
  const end = html.indexOf('<!-- LIVE -->', pinAt);
  const block = pinAt >= 0 && end > pinAt ? html.slice(pinAt, end) : "";
  if (block.includes('id="live_rhead"') && block.includes('id="hangup_btn"')) ok("the store card AND Stop & hang up both ride inside the pin");
  else no("the pin lost the store card or the hang-up button — the owner needs the hang-up pinned with the card");
}

// 4. Sticky, never fixed (trap 1).
has(/body\.lview #live_pin,body\.pendbox #live_pin\{display:block;position:sticky/,
  "the card is position:sticky on both the call screen and the pull screen");
absent(/#live_pin\s*\{[^}]*position:\s*fixed/,
  "the card is NEVER position:fixed — a fixed filled box is what flipped the iOS bottom bar grey (trap 1)");

// 5. Hidden unless one of the two states is on. It sits in <main> full-time now, so it must default off.
has(/#live_pin\{display:none\}/,
  "the card defaults to display:none — it lives in <main> full-time and must not leak onto other screens");

// 6. The offset clears the notch. Sticky measures from the viewport, not from body's safe-area padding.
has(/#live_pin\{display:block;position:sticky;top:env\(safe-area-inset-top\)/,
  "the card's sticky offset clears the notch (env(safe-area-inset-top))");

// ── B. The scroll surface: the DOCUMENT scrolls, nothing else ──

// 7. Trap 3. Without this the sticky is dead on arrival.
has(/body\.lview,body\.pendbox\{overflow-x:clip;overflow-y:visible\}/,
  "body stops being its own scrollport on this page (overflow-x:clip, not hidden) — trap 3");

// 8. No inner scroller. The conversation must ride the real page scroll; an inner pane is how the page
//    stops scrolling, and a page that cannot scroll is what put the grey bar back.
absent(/#live_msgbox\s*\{[^}]*overflow-y:\s*(auto|scroll)/,
  "the conversation is NOT put in its own scroller — it rides the document scroll");
absent(/#live_pin\s*\{[^}]*overflow-y:\s*(auto|scroll)/,
  "the pin is not a scroller either");

// 9. The standing no-forced-height rule (also guarded in qa-tint-lock, repeated here where it belongs).
absent(/body\.lview\s+#live\s*\{[^}]*min-height/,
  "the live view is never padded to a forced height to chase the tint (tried 07-30, reverted same day)");

// ── C. The footer leaves for the call and comes back at the reveal ──

// 10. Gone for both pre-reveal screens.
has(/body\.lview \.site-footer,body\.rv-pend \.site-footer\{display:none\}/,
  "the footer is gone for the call AND the pull screen, and returns on its own at the reveal");

// 11. It must NOT be hidden by anything wider — the result page keeps its footer like every other page.
absent(/body\.rview\s+\.site-footer\s*\{\s*display:\s*none/,
  "the result page keeps its footer (the call-page rule must never widen to rview)");

// ── D. The pull screen: the card stays, says "Getting results", and leaves with the verdict ──

// 12. The state class is set from the pending render and only for a call we were just watching.
has(/const _keepBox = !!\(o && o\.status==='pending' && \(_fromLive \|\| window\._livePend\)\)/,
  "the pull-screen state is armed ONLY for a call we were just watching (a mid-call refresh is untouched)");
has(/document\.body\.classList\.toggle\('pendbox', _keepBox\)/,
  "body.pendbox is toggled on EVERY render — it can never get stuck on");

// 13. It is cleared on the way back to the homepage too.
has(/document\.body\.classList\.remove\('pendbox'\)/,
  "body.pendbox is cleared on the way home (backToBuilder) — no leak onto the next check");

// 14. The card carries the message, so the result frame must not print it a second time.
has(/body\.pendbox #result \.rverdict\{display:none\}/,
  "the result frame skips its placeholder headline while the card carries the message");

// 15. The headline the owner asked for, verbatim.
has(/t\('live\.h4','Getting results'\)/,
  "the card reads \"Getting results\" while the verdict is being pulled (owner's words)");
has(/'live\.h4':'[^']+'/,
  "the pull headline is translated (live.h4 exists in the ES table)");

// ── E. The browser proof cannot be deleted ──
// This page is behavioural. Static rules alone would not have caught trap 2 — a real browser scrolling a
// real pull screen did. These guard that proof.

const lHas = (re, m) => (re.test(live) ? ok(m) : no(m));
lHas(/store card \+ hang-up stay pinned while the conversation scrolls/,
  "test-live-view still proves the card holds while the CALL screen scrolls");
lHas(/the card holds while the pull screen scrolls/,
  "test-live-view still proves the card holds while the PULL screen scrolls (trap 2's only real witness)");
lHas(/window\.scrollTo\(0, document\.documentElement\.scrollHeight\)/,
  "the pull-screen check measures the page SCROLLED, not at rest — at rest it proved nothing and let trap 2 ship");
lHas(/the pull screen never got tall enough to scroll/,
  "the pull-screen check FAILS honestly when the screen was too short to prove anything");
lHas(/document\.body\.classList\.remove\("sheetopen"\)/,
  "the pull-screen check clears any open sheet first — a dimmed, locked page parks every sticky by design");
lHas(/footer is gone during the call/,
  "test-live-view still proves the footer leaves for the call");
lHas(/footer comes back at the reveal/,
  "test-live-view still proves the footer comes back at the reveal");
lHas(/the card disappears the moment the verdict lands/,
  "test-live-view still proves the card leaves with the verdict");

if (/qa-checkpage-lock\.mjs/.test(all)) ok("this lock is wired into test-all.sh (CI runs it on every ship)");
else no("this lock is NOT in test-all.sh — an unwired gate protects nothing");
if (/test-live-view\.sh/.test(all)) ok("the live-view browser lock is still wired into test-all.sh");
else no("the live-view browser lock was unwired from test-all.sh");

console.log(`\n  check page lock PASS: ${pass}  FAIL: ${fail}\n`);
process.exit(fail ? 1 : 0);
